import{_ as n,a0 as i,w as p,s as m,ao as r,I as o,x as u,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何在Ubuntu桌面上使用Steam Music音樂播放器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu桌面上使用Steam Music音樂播放器 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu桌面上使用Steam Music音樂播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu桌面上使用Steam Music音樂播放器 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141008 How To Use Steam Music Player on Ubuntu Desktop","title":"如何在Ubuntu桌面上使用Steam Music音樂播放器","tag":"201412","desc":""},"relativePath":"201412/20141008 How To Use Steam Music Player on Ubuntu Desktop.md","filePath":"[post].md"}'),l={name:"201412/20141008 How To Use Steam Music Player on Ubuntu Desktop.md"};function g(c,t,d,w,b,S){const e=i("Link");return p(),m("div",null,[t[13]||(t[13]=r('<h1 id="如何在ubuntu桌面上使用steam-music音樂播放器" tabindex="-1">如何在Ubuntu桌面上使用Steam Music音樂播放器 <a class="header-anchor" href="#如何在ubuntu桌面上使用steam-music音樂播放器" aria-label="Permalink to “如何在Ubuntu桌面上使用Steam Music音樂播放器”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/steam-music.jpg" alt=""></p><p><strong>‘音樂讓人們走到一起’ 麥當娜曾這樣唱道。但是Steam的新音樂播放器特性能否很好的混搭小資與叛逆？</strong></p><p>如果你曾與世隔絕，充耳不聞，你就會錯過與Steam Music的相識。它的特性並不是全新的。從今年的早些時候開始，它就已經以這樣或那樣的形式進行了測試。</p><p>但Steam客户端最近一次在Windows、Mac和Linux上的定期更新中，所有的客户端都能使用它了。你會問為什麼一個遊戲客户端會添加一個音樂播放器呢？當然是為了讓你能一邊玩遊戲一邊一邊聽你最喜歡的音樂了。</p><p>別擔心：在遊戲的音樂聲中再加上你自己的音樂，聽起來並不會像你想像的那麼糟（哈哈）。Steam會幫你減少或消除遊戲的背景音樂，但在混音器中保持效果音的高音量，以便於你能和平時一樣聽到那些叮，嘭和各種爆炸聲。</p><h3 id="使用steam-music音樂播放器" tabindex="-1">使用Steam Music音樂播放器 <a class="header-anchor" href="#使用steam-music音樂播放器" aria-label="Permalink to “使用Steam Music音樂播放器”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-music-bpm.jpg" alt="Music in Big Picture Mode"></p><p><em>大圖模式</em></p><p>任何使用最新版客户端的人都能使用Steam Music音樂播放器。它是個相當簡單的附加程序：它讓你能從你的電腦中添加、瀏覽並播放音樂。</p><p>播放器可以以兩種方式進入：桌面和（超棒的）Steam大圖模式。在兩種方式下，控制播放都超級簡單。</p><p>作為一個Rhythmbox的對手或是Spotify的繼承者，把<strong>為玩遊戲時放音樂而設計</strong>作為特點一點也不吸引人。事實上，他沒有任何可購買音樂的商店，也沒有整合Rdio，Grooveshark這類在線服務或是桌面服務。沒錯，你的多媒體鍵在Linux的播放器上完全不能用。</p><p>Valve説他們“<em>……計劃增加更多的功能以便用户能以新的方式體驗Steam Music。我們才剛剛開始。</em>”</p><h4 id="steam-music的重要特性" tabindex="-1">Steam Music的重要特性：#### <a class="header-anchor" href="#steam-music的重要特性" aria-label="Permalink to “Steam Music的重要特性：####”">​</a></h4><ul><li>只能播放MP3文件</li><li>與遊戲中的音樂相融</li><li>在遊戲中可以控制音樂</li><li>播放器可以在桌面上或在大圖模式下運行</li><li>基於播放列表的播放方式</li></ul><p><strong>它沒有整合到Ubuntu的聲音菜單裏，而且目前也不支持鍵盤上的多媒體鍵。</strong></p><h3 id="在ubuntu上使用steam-music播放器" tabindex="-1">在Ubuntu上使用Steam Music播放器 <a class="header-anchor" href="#在ubuntu上使用steam-music播放器" aria-label="Permalink to “在Ubuntu上使用Steam Music播放器”">​</a></h3><p>顯然，添加音樂是你播放音樂前的第一件事。在Ubuntu上，默認設置下，Steam會自動添加兩個文件夾：Home下的標準Music目錄和它自帶的Steam Music文件夾。任何可下載的音軌都保存在其中。</p><p>注意：目前<strong>Steam Music只能播放MP3文件</strong>。如果你的大部分音樂都是其他文件格式（比如.acc、.m4a等等），這些文件不會被添加也不能被播放。</p><p>若想添加其他的文件夾或重新掃描：</p><ul><li>到<strong>View &gt; Settings &gt; Music</strong>。</li><li>點擊‘<strong>Add</strong>‘將其他位置的文件夾添加到已列出兩個文件夾的列表下。</li><li>點擊‘<strong>Start Scanning</strong>’</li></ul><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/Tardis.jpg" alt=""></p><p>你還可以在這個對話框中調整其他設置，包括‘scan at start’。如果你經常添加新音樂而且很容易忘記手動啓動掃描，請標記此項。你還可以選擇當路徑變化時是否顯示提示，設置默認的音量，還能調整當你打開一個應用軟件或語音聊天時的播放狀態的改變。</p><p>一旦你的音樂源成功的被添加並掃描後，你就可以通過主客户端的<strong>Library &gt; Music</strong>區域瀏覽你的音樂了。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/browser.jpg" alt=""></p><p>Steam Music會默認的將音樂按照專輯進行分組。若想按照樂隊名進行瀏覽，你需要點擊‘Albums’然後從下拉菜單中選擇‘Artists’。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-selection.jpg" alt=""></p><p>Steam Music是一個以‘隊列’方式工作的系統。你可以通過雙擊瀏覽器裏的音樂或右鍵單擊並選擇‘Add to Queue’來把音樂添加到播放隊列裏。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-music-queue.jpg" alt=""></p><p>若想<strong>啓動桌面播放器</strong>請點擊右上角的音符圖標或通過<strong>View &gt; Music Player</strong>菜單。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-music.jpg" alt=""></p><hr>',32)),o("p",null,[t[1]||(t[1]=u("via: ",-1)),s(e,{href:"http://www.omgubuntu.co.uk/2014/10/use-steam-music-player-linux"},{default:a(()=>[...t[0]||(t[0]=[u("http://www.omgubuntu.co.uk/2014/10/use-steam-music-player-linux",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=u("作者：",-1)),s(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[2]||(t[2]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[6]||(t[6]=u(" 譯者：",-1)),s(e,{href:"https://github.com/H-mudcup"},{default:a(()=>[...t[3]||(t[3]=[u("H-mudcup",-1)])]),_:1}),t[7]||(t[7]=u(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[u("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=u("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[u("LCTT",-1)])]),_:1}),t[11]||(t[11]=u(" 原創翻譯，",-1)),s(e,{href:"http://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[u("Linux中國",-1)])]),_:1}),t[12]||(t[12]=u(" 榮譽推出",-1))])])}const f=n(l,[["render",g]]);export{h as __pageData,f as default};
